/// Given a list of poker hands, return a list of those hands which win.
///
/// Note the type signature: this function should return _the same_ reference to
/// the winning hand(s) as were passed in, not reconstructed strings which happen to be equal.
pub fn winning_hands<'a>(hands: &[&'a str]) -> Vec<&'a str> {
    let mut scored: Vec<(&'a str, Hand)> = hands.iter().map(|h| (*h, Hand::parse(h))).collect();

    // Sort isn't needed; just find the best score and collect every hand matching it.
    let best = scored
        .iter()
        .map(|(_, h)| h.score())
        .max()
        .expect("at least one hand");

    scored
        .drain(..)
        .filter(|(_, h)| h.score() == best)
        .map(|(s, _)| s)
        .collect()
}

/// Strength of a hand: `(category, tiebreakers)`.
///
/// `Ord` on this tuple gives exactly the ordering we need: categories are
/// compared first, and ties are broken lexicographically by the tiebreaker
/// ranks (which always have the same length within a category).
type Score = (u8, Vec<u8>);

#[derive(Debug, Clone)]
struct Hand {
    ranks: Vec<u8>,
    suits: Vec<u8>,
}

impl Hand {
    fn parse(s: &str) -> Self {
        let mut ranks = Vec::new();
        let mut suits = Vec::new();

        for card in s.split_whitespace() {
            let (rank_str, suit_str) = card.split_at(card.len() - 1);
            let rank = match rank_str {
                "A" => 14,
                "K" => 13,
                "Q" => 12,
                "J" => 11,
                other => other.parse::<u8>().expect("valid rank"),
            };
            let suit = suit_str.bytes().next().expect("a suit");
            ranks.push(rank);
            suits.push(suit);
        }

        Self { ranks, suits }
    }

    fn score(&self) -> Score {
        // Highest card first.
        let mut desc = self.ranks.clone();
        desc.sort_unstable_by(|a, b| b.cmp(a));

        let is_flush = self.suits.windows(2).all(|w| w[0] == w[1]);

        // Rank groups ordered by size, then by rank (both descending).
        let mut groups: Vec<(u8, usize)> = Vec::new();
        for &rank in &desc {
            match groups.iter_mut().find(|g| g.0 == rank) {
                Some(g) => g.1 += 1,
                None => groups.push((rank, 1)),
            }
        }
        groups.sort_by(|a, b| b.1.cmp(&a.1).then(b.0.cmp(&a.0)));

        // The highest card of a straight, if any (A can be high or low).
        let straight_high = straight_high(&desc);

        let counts: Vec<usize> = groups.iter().map(|&(_, c)| c).collect();

        let category: u8;
        let tiebreak: Vec<u8>;

        if let Some(high) = straight_high {
            if is_flush {
                category = 8; // straight flush
                tiebreak = vec![high];
            } else {
                category = 4; // straight
                tiebreak = vec![high];
            }
        } else {
            match counts.as_slice() {
                [4, ..] => {
                    category = 7; // four of a kind
                    tiebreak = groups.iter().map(|&(r, _)| r).take(2).collect();
                }
                [3, 2, ..] => {
                    category = 6; // full house
                    tiebreak = groups.iter().map(|&(r, _)| r).take(2).collect();
                }
                [3, ..] => {
                    category = 3; // three of a kind
                    tiebreak = groups.iter().map(|&(r, _)| r).collect();
                }
                [2, 2, ..] => {
                    category = 2; // two pair
                    tiebreak = groups.iter().map(|&(r, _)| r).collect();
                }
                [2, ..] => {
                    category = 1; // one pair
                    tiebreak = groups.iter().map(|&(r, _)| r).collect();
                }
                _ if is_flush => {
                    category = 5; // flush
                    tiebreak = desc.clone();
                }
                _ => {
                    category = 0; // high card
                    tiebreak = desc.clone();
                }
            }
        }

        (category, tiebreak)
    }
}

/// Returns the highest card of the straight formed by these ranks, or `None`.
///
/// An ace may cap a straight (10-J-Q-K-A) or start one (A-2-3-4-5), but never
/// sit in the middle (Q-K-A-2-3 is not a straight).
fn straight_high(desc_sorted: &[u8]) -> Option<u8> {
    let mut uniq: Vec<u8> = desc_sorted.to_vec();
    uniq.dedup();

    if uniq.len() < 5 {
        return None;
    }

    // Look for any run of five consecutive ranks.
    for w in uniq.windows(5) {
        if w[0].saturating_sub(4) == w[4] && w.iter().enumerate().all(|(i, &r)| r == w[0] - i as u8)
        {
            // Ace may only be the top card of a straight.
            if w.contains(&14) && w[0] != 14 {
                continue;
            }
            return Some(w[0]);
        }
    }

    // Wheel: A-5-4-3-2 (the ace plays low, so the straight is five-high).
    if uniq.starts_with(&[14, 5]) {
        return Some(5);
    }

    None
}

