/// Strength of a hand: `(category, tiebreakers)`.
///
/// Ordering of this tuple is exactly the ordering we need: the category decides
/// first, and ties within a category are broken lexicographically by the
/// tiebreaker ranks (which always have the same length for a given category).
type Score = (u8, Vec<u8>);

const HIGH_CARD: u8 = 0;
const ONE_PAIR: u8 = 1;
const TWO_PAIR: u8 = 2;
const THREE_OF_A_KIND: u8 = 3;
const STRAIGHT: u8 = 4;
const FLUSH: u8 = 5;
const FULL_HOUSE: u8 = 6;
const FOUR_OF_A_KIND: u8 = 7;
const STRAIGHT_FLUSH: u8 = 8;

#[derive(Debug, Clone)]
struct Hand {
    ranks: Vec<u8>,
    suits: Vec<u8>,
}

impl Hand {
    fn parse(s: &str) -> Self {
        let mut ranks = Vec::new();
        let mut suits = Vec::new();

        for card in s.split_whitespace() {
            let (rank_str, suit_str) = card.split_at(card.len() - 1);
            let rank = match rank_str {
                "A" => 14,
                "K" => 13,
                "Q" => 12,
                "J" => 11,
                other => other.parse::<u8>().expect("card with a valid rank"),
            };
            let suit = suit_str.as_bytes().first().copied().expect("card suit");
            ranks.push(rank);
            suits.push(suit);
        }

        Self { ranks, suits }
    }

    fn score(&self) -> Score {
        // Ranks sorted from highest to lowest.
        let mut desc = self.ranks.clone();
        desc.sort_unstable_by(|a, b| b.cmp(a));

        let is_flush = self.suits.windows(2).all(|w| w[0] == w[1]);
        let straight_high = straight_high(&desc);

        // Cards grouped by rank, ordered by group size and then by rank (both
        // descending) so that e.g. two pairs and their kicker come out ordered.
        let mut groups: Vec<(u8, usize)> = Vec::new();
        for &rank in &desc {
            match groups.iter_mut().find(|g| g.0 == rank) {
                Some(g) => g.1 += 1,
                None => groups.push((rank, 1)),
            }
        }
        groups.sort_by(|a, b| b.1.cmp(&a.1).then(b.0.cmp(&a.0)));
        let ranks_of_groups: Vec<u8> = groups.iter().map(|&(r, _)| r).collect();
        let counts: Vec<usize> = groups.iter().map(|&(_, c)| c).collect();

        let category;
        let tiebreak: Vec<u8>;

        if let Some(high) = straight_high {
            if is_flush {
                category = STRAIGHT_FLUSH;
            } else {
                category = STRAIGHT;
            }
            tiebreak = vec![high];
        } else if is_flush {
            category = FLUSH;
            tiebreak = desc.clone();
        } else {
            match counts.as_slice() {
                [4, ..] => {
                    category = FOUR_OF_A_KIND;
                    tiebreak = ranks_of_groups.iter().copied().take(2).collect();
                }
                [3, 2, ..] => {
                    category = FULL_HOUSE;
                    tiebreak = ranks_of_groups.iter().copied().take(2).collect();
                }
                [3, ..] => {
                    category = THREE_OF_A_KIND;
                    tiebreak = ranks_of_groups.clone();
                }
                [2, 2, ..] => {
                    category = TWO_PAIR;
                    tiebreak = ranks_of_groups.clone();
                }
                [2, ..] => {
                    category = ONE_PAIR;
                    tiebreak = ranks_of_groups.clone();
                }
                _ => {
                    category = HIGH_CARD;
                    tiebreak = desc.clone();
                }
            }
        }

        (category, tiebreak)
    }
}

/// The highest card of a straight contained in these ranks, or `None`.
///
/// `ranks` must be sorted descending. An ace may cap a straight
/// (10-J-Q-K-A) or start one (A-2-3-4-5), but never sit in the middle, so
/// Q-K-A-2-3 is not a straight.
fn straight_high(ranks: &[u8]) -> Option<u8> {
    let mut uniq: Vec<u8> = ranks.to_vec();
    uniq.dedup();

    if uniq.len() < 5 {
        return None;
    }

    for w in uniq.windows(5) {
        let high = u16::from(w[0]);
        let consecutive = w
            .iter()
            .enumerate()
            .all(|(i, &r)| u16::from(r) == high - i as u16);
        if !consecutive {
            continue;
        }
        // Reject straights that wrap through the middle of the ace, such as
        // K-A-2-3-4 (the sequence 14,13,12,11,10 style runs are fine).
        let crosses_ace = w.contains(&14) && w[0] != 14 && w[4] != 9;
        if crosses_ace {
            continue;
        }
        return Some(w[0]);
    }

    // The wheel: A-5-4-3-2, where the ace plays low, making it a six-low
    // ... that is, a five-high straight (the lowest scoring one).
    if uniq.starts_with(&[14, 5, 4, 3, 2]) {
        return Some(5);
    }

    None
}

